 36→test('normativa index sorts regulations by severity then date', function () {
 37→    Regulation::factory()->info()->create([
 38→        'exploitation_id' => $this->exploitation->id,
 39→        'title' => 'Info alert',
 40→    ]);
 41→    Regulation::factory()->urgent()->create([
 42→        'exploitation_id' => $this->exploitation->id,
 43→        'title' => 'Urgent alert',
 44→    ]);
 45→    Regulation::factory()->warning()->create([
 46→        'exploitation_id' => $this->exploitation->id,
 47→        'title' => 'Warning alert',
 48→    ]);
 49→
 50→    $this->actingAs($this->user)
 51→        ->get(route('normativa.index'))
 52→        ->assertSuccessful()
 53→        ->assertInertia(fn ($page) => $page
 54→            ->component('normativa/index')
 55→            ->has('regulations', 3)
 56→            ->where('regulations.0.severity', 'urgent')
 57→            ->where('regulations.1.severity', 'warning')
 58→            ->where('regulations.2.severity', 'info')
 59→        );
 60→});
 61→
 62→test('normativa index only shows regulations for the users exploitation', function () {
 63→    $otherExploitation = Exploitation::factory()->create();
 64→
 65→    Regulation::factory()->create(['exploitation_id' => $this->exploitation->id]);
 66→    Regulation::factory()->create(['exploitation_id' => $otherExploitation->id]);
 67→
 68→    $this->actingAs($this->user)
 69→        ->get(route('normativa.index'))
 70→        ->assertSuccessful()
 71→        ->assertInertia(fn ($page) => $page
 72→            ->has('regulations', 1)
 73→        );
 74→});
 75→
 76→test('normativa index returns severity counts', function () {
 77→    Regulation::factory()->urgent()->count(2)->create(['exploitation_id' => $this->exploitation->id]);
 78→    Regulation::factory()->warning()->count(3)->create(['exploitation_id' => $this->exploitation->id]);
 79→    Regulation::factory()->info()->count(1)->create(['exploitation_id' => $this->exploitation->id]);
 80→
 81→    $this->actingAs($this->user)
 82→        ->get(route('normativa.index'))
 83→        ->assertSuccessful()
 84→        ->assertInertia(fn ($page) => $page
 85→            ->where('counts.urgent', 2)
 86→            ->where('counts.warning', 3)
 87→            ->where('counts.info', 1)
