 91→test('can mark regulation as read', function () {
 92→    $regulation = Regulation::factory()->create([
 93→        'exploitation_id' => $this->exploitation->id,
 94→        'is_read' => false,
 95→    ]);
 96→
 97→    $this->actingAs($this->user)
