104→test('can mark regulation as resolved', function () {
105→    $regulation = Regulation::factory()->create([
106→        'exploitation_id' => $this->exploitation->id,
107→        'is_resolved' => false,
108→    ]);
109→
110→    $this->actingAs($this->user)
111→        ->patch(route('api.regulations.resolve', $regulation))
112→        ->assertSuccessful();
113→
114→    expect($regulation->fresh()->is_resolved)->toBeTrue();
