124→test('authenticated users can view sanitary campaign detail', function () {
125→    $campaign = SanitaryCampaign::factory()->create(['exploitation_id' => $this->exploitation->id]);
126→    $sub = SubExploitation::factory()->create(['exploitation_id' => $this->exploitation->id]);
