147→test('sanitary campaign groups animals by status', function () {
148→    $campaign = SanitaryCampaign::factory()->create(['exploitation_id' => $this->exploitation->id]);
149→    $sub = SubExploitation::factory()->create(['exploitation_id' => $this->exploitation->id]);
150→
151→    $animals = Animal::factory()->count(5)->create(['sub_exploitation_id' => $sub->id]);
152→
153→    CampaignAnimal::factory()->create(['sanitary_campaign_id' => $campaign->id, 'animal_id' => $animals[0]->id, 'status' => 'sampled']);
154→    CampaignAnimal::factory()->create(['sanitary_campaign_id' => $campaign->id, 'animal_id' => $animals[1]->id, 'status' => 'sampled']);
155→    CampaignAnimal::factory()->create(['sanitary_campaign_id' => $campaign->id, 'animal_id' => $animals[2]->id, 'status' => 'pending']);
156→    CampaignAnimal::factory()->immobilized()->create(['sanitary_campaign_id' => $campaign->id, 'animal_id' => $animals[3]->id]);
157→    CampaignAnimal::factory()->immobilized()->create(['sanitary_campaign_id' => $campaign->id, 'animal_id' => $animals[4]->id]);
158→
159→    $this->actingAs($this->user)
160→        ->get(route('normativa.campanas.show', $campaign))
161→        ->assertSuccessful()
162→        ->assertInertia(fn ($page) => $page
163→            ->has('animals.sampled', 2)
164→            ->has('animals.pending', 1)
165→            ->has('animals.immobilized', 2)
